def calculate_transmission_deadline(D_m, J_m):
    E_m = D_m - J_m
    return E_m

def calculate_response_time(w_m, C_m):
    R_m = w_m + C_m
    return R_m

def is_message_schedulable(message_m):
    return message_m.R <= message_m.E

def is_system_schedulable(message_set):
    for message_m in message_set:
        if not is_message_schedulable(message_m):
            return False
    return True

def is_fifo_adjacent_ordering(message_set, priority_map):
    fifo_groups = group_messages_by_fifo_queue(message_set)
    for group_id, messages_in_group in fifo_groups.items():
        group_priorities = sorted([priority_map[msg.id] for msg in messages_in_group])
        # Check if priorities are contiguous
        for i in range(len(group_priorities) - 1):
            if group_priorities[i+1] - group_priorities[i] != 1:
                return False # Not adjacent
        # Check if any other message has a priority within this range
        min_p = group_priorities[0]
        max_p = group_priorities[-1]
        for msg in message_set:
            if msg not in messages_in_group:
                if min_p <= priority_map[msg.id] <= max_p:
                    return False # Interleaving found
    return True

def calculate_blocking_factor(message_m, message_set):
    B_m = 0
    for message_k in message_set:
        if message_k.priority > message_m.priority: # Assuming higher number = lower priority
            B_m = max(B_m, message_k.C)
    return B_m

def calculate_fifo_internal_interference(message_m, message_set):
    fifo_group_id = message_m.fifo_group_id
    SUM_C_other_in_FIFO_group_m = 0
    for message_j in message_set:
        if message_j.fifo_group_id == fifo_group_id and message_j.id != message_m.id:
            SUM_C_other_in_FIFO_group_m += message_j.C
    return SUM_C_other_in_FIFO_group_m

def calculate_buffering_time(R_m, C_m):
    f_m = R_m - C_m
    return f_m

def schedulability_test_algorithm_1(message_set):
    f_values = {msg.id: 0 for msg in message_set if not msg.is_priority_queued}

    while True:
        f_values_old = f_values.copy()

        # Sort messages by priority (e.g., highest priority first)
        sorted_messages = sorted(message_set, key=lambda msg: msg.priority) # Assuming lower number = higher priority

        for message_m in sorted_messages:
            if message_m.is_priority_queued:
                w_m = calculate_w_m_pq_mixed(message_m, message_set, f_values)
            else: # FIFO-queued
                w_m = calculate_w_m_fq_mixed(message_m, message_set, f_values)

            message_m.R = w_m + message_m.C

            if not message_m.is_priority_queued:
                f_values[message_m.id] = message_m.R - message_m.C

        # Check for convergence
        if all(f_values[msg_id] == f_values_old[msg_id] for msg_id in f_values):
            break

    # Final schedulability check
    for message_m in message_set:
        if message_m.R > message_m.E:
            return False # System is not schedulable
    return True # System is schedulable

